export const getCardSizes = (useSmallImages) => {
    const imgWidth = useSmallImages ? 480 : 720;
    const imgHeight = useSmallImages ? 300 : 450;
    const footerHeight = useSmallImages ? 64 : 64;
    return {
        imgWidth,
        imgHeight,
        footerHeight,
    };
};
export const getSeasons = (collection) => {
    const series = [];
    for (const name of Object.keys(collection.series)) {
        const season = collection.series[name] ?? [];
        if (!season.length) {
            continue;
        }
        series.push({
            collection: name,
            thumbnail: season[0].thumbnail,
        });
    }
    return series;
};
export const getCollectionsAndVideos = (activeSeries, currentSeason) => {
    if (activeSeries.collection === "") {
        return {
            child_collections: activeSeries.child_collections,
            videos: activeSeries.videos
        };
    }
    if (typeof currentSeason !== "undefined") {
        return {
            child_collections: [],
            videos: activeSeries.series[currentSeason] || []
        };
    }
    const seasons = getSeasons(activeSeries);
    if (!seasons.length) {
        return {
            child_collections: [],
            videos: activeSeries.videos
        };
    }
    if (seasons.length === 1 && seasons[0].collection === "") {
        return {
            child_collections: [],
            videos: activeSeries.series[seasons[0].collection] || []
        };
    }
    return {
        child_collections: getSeasons(activeSeries),
        videos: [] //activeSeries.series?.[""] ?? [],
    };
};
