import { invoke } from '@tauri-apps/api/core';
/**
 * Implementation of a Rest Adaptor using Tauri IPC
 */
export class TauriRestAdaptor {
    constructor() {
        this.getHost = () => {
            // In Tauri, there's no traditional "host" for the backend connection
            return null;
        };
        this.getSocketHost = (host, protocol, path) => {
            // WebSocket simulation will be handled differently via Tauri events
            // This method might become obsolete or needs reimplementation for Tauri events
            console.warn('getSocketHost is not directly applicable in Tauri mode.');
            return `tauri-event://${path}`;
        };
    }
    async get(path, options) {
        // Remove leading slash if present
        const cleanPath = path.startsWith('/') ? path.substring(1) : path;
        console.log(`Tauri GET: /api/${cleanPath}`);
        // Handle query parameters (e.g., for search)
        const [basePath, queryString] = cleanPath.split('?');
        const params = new URLSearchParams(queryString);
        try {
            switch (basePath) {
                case 'tasks':
                    return await invoke('tasks_list');
                case 'media':
                    // Root collection
                    return await invoke('list_root_collection');
                case 'remote':
                    return await invoke('list_player');
                case 'conversion':
                    return await invoke('list_conversions');
                // Cases needing parameter extraction
                case 'search/pirate':
                    const pirateQuery = params.get('q');
                    if (!pirateQuery)
                        throw new Error('Missing query parameter q for pirate search');
                    return await invoke('pirate_search', { query: pirateQuery });
                case 'search/youtube':
                    const youtubeQuery = params.get('q');
                    if (!youtubeQuery)
                        throw new Error('Missing query parameter q for youtube search');
                    return await invoke('youtube_search', { query: youtubeQuery });
                default:
                    // Handle paths with parameters (e.g., /media/some/collection)
                    if (basePath.startsWith('media/')) {
                        const collection = basePath.substring('media/'.length);
                        return await invoke('list_collection', { collection });
                    }
                    throw new Error(`Unhandled GET path: ${basePath}`);
            }
        }
        catch (error) {
            console.error(`Error invoking GET ${path}:`, error);
            // Rethrow or handle error appropriately
            throw new Error(`Tauri invocation failed for GET ${path}: ${error}`);
        }
    }
    async post(path, payload) {
        const cleanPath = path.startsWith('/') ? path.substring(1) : path;
        console.log(`Tauri POST: /api/${cleanPath}`, payload);
        const command = this.mapPathToCommand('POST', cleanPath);
        const args = this.prepareArgs('POST', cleanPath, payload);
        try {
            const result = await invoke(command, args);
            // Simulate a successful standard Response object
            return this.simulateResponse(200, 'OK', result);
        }
        catch (error) {
            console.error(`Error invoking POST ${path}:`, error);
            // Simulate an error standard Response object
            const errorMessage = String(error);
            return this.simulateResponse(500, 'Internal Server Error', { success: false, message: errorMessage });
        }
    }
    async put(path, payload) {
        console.warn(`PUT method not mapped yet for path: ${path}`);
        // Simulate a 'Not Implemented' standard Response
        return this.simulateResponse(501, 'Not Implemented', { success: false, message: 'Not Implemented' });
    }
    async patch(path, payload) {
        const cleanPath = path.startsWith('/') ? path.substring(1) : path;
        console.log(`Tauri PATCH: /api/${cleanPath}`, payload);
        const command = this.mapPathToCommand('PATCH', cleanPath);
        const args = this.prepareArgs('PATCH', cleanPath, payload);
        try {
            const result = await invoke(command, args);
            return this.simulateResponse(200, 'OK', result);
        }
        catch (error) {
            console.error(`Error invoking PATCH ${path}:`, error);
            const errorMessage = String(error);
            return this.simulateResponse(500, 'Internal Server Error', { success: false, message: errorMessage });
        }
    }
    async delete(path) {
        const cleanPath = path.startsWith('/') ? path.substring(1) : path;
        console.log(`Tauri DELETE: /api/${cleanPath}`);
        const command = this.mapPathToCommand('DELETE', cleanPath);
        const args = this.prepareArgs('DELETE', cleanPath);
        try {
            const result = await invoke(command, args);
            return this.simulateResponse(200, 'OK', result);
        }
        catch (error) {
            console.error(`Error invoking DELETE ${path}:`, error);
            const errorMessage = String(error);
            return this.simulateResponse(500, 'Internal Server Error', { success: false, message: errorMessage });
        }
    }
    // Helper to map path and method to Tauri command
    mapPathToCommand(method, path) {
        if (method === 'POST' && path === 'tasks')
            return 'tasks_add';
        if (method === 'POST' && path === 'log')
            return 'log_client_message';
        if (method === 'POST' && path === 'remote/control')
            return 'remote_command';
        if (method === 'POST' && path === 'remote/play')
            return 'remote_play';
        if (method === 'POST' && path.match(/^media\/[^\/]+$/))
            return 'convert_video';
        if (method === 'PATCH' && path === 'tasks')
            return 'download_videos';
        if (method === 'PATCH' && path.match(/^media\/[^\/]+$/))
            return 'share_video'; // Assuming share uses PATCH
        if (method === 'DELETE' && path.match(/^tasks\/[^\/]+\/[^\/]+$/))
            return 'tasks_delete';
        if (method === 'DELETE' && path.match(/^media\/[^\/]+$/))
            return 'delete_video';
        throw new Error(`Cannot map ${method} ${path} to Tauri command`);
    }
    // Helper to prepare arguments for invoke
    prepareArgs(method, path, payload) {
        if (method === 'POST' && path === 'tasks')
            return { payload };
        if (method === 'PATCH' && path === 'tasks')
            return { payload };
        if (method === 'POST' && path === 'log')
            return { payload };
        if (method === 'POST' && path === 'remote/control')
            return { payload };
        if (method === 'POST' && path === 'remote/play')
            return { payload };
        if (method === 'POST' && path.match(/^media\/([^\/]+)$/)) {
            const videoId = RegExp.$1; // Keep as string to preserve int64 precision
            return { videoId, request: payload }; // Matches convert_video signature
        }
        if (method === 'PATCH' && path.match(/^media\/([^\/]+)$/)) {
            const videoId = RegExp.$1; // Keep as string to preserve int64 precision
            // Assuming share_video only needs the ID, adjust if payload is needed
            return { videoId }; // Matches share_video signature
        }
        if (method === 'DELETE' && path.match(/^tasks\/([^\/]+)\/(.+)$/)) {
            // TaskType seems unused in the Rust command, but we capture it
            const taskType = RegExp.$1;
            const key = decodeURIComponent(RegExp.$2);
            // Note: Rust command `tasks_delete` signature takes `state, _, key`
            // We only need to pass the `key` from the frontend.
            return { key };
        }
        if (method === 'DELETE' && path.match(/^media\/([^\/]+)$/)) {
            const videoId = RegExp.$1; // Keep as string to preserve int64 precision
            return { videoId }; // Matches delete_video signature
        }
        return payload ? { payload } : {}; // Default or fallback
    }
    // Simulate a Response object compatible with the Fetch API standard Response
    simulateResponse(status, statusText, body) {
        const bodyString = JSON.stringify(body);
        const headers = new Headers({
            'Content-Type': 'application/json',
            'Content-Length': new TextEncoder().encode(bodyString).length.toString(),
        });
        const responseBlob = new Blob([bodyString], { type: 'application/json' });
        // Create an object that mimics the Response interface
        const simulatedResponse = {
            ok: status >= 200 && status < 300,
            status: status,
            statusText: statusText,
            headers: headers,
            url: 'tauri://localhost', // Placeholder URL
            redirected: false,
            type: 'basic', // Use ResponseType enum/literal type
            body: responseBlob.stream(), // Use Blob stream
            bodyUsed: false,
            json: async () => JSON.parse(bodyString),
            text: async () => bodyString,
            arrayBuffer: async () => responseBlob.arrayBuffer(),
            blob: async () => responseBlob,
            formData: async () => { throw new Error('formData() not implemented in simulation'); }, // Add if needed
            clone: () => this.simulateResponse(status, statusText, body), // Basic clone
        };
        // Cast to unknown first, then to Response to bypass strict overlap checks
        return simulatedResponse;
    }
}
