import { configureStore } from '@reduxjs/toolkit';
import searchReducer from "./SearchReducer";
import remoteMessageReducer from "./EventReducer";
import seriesReducer from "./SeriesReducer";
import configReducer from "./ConfigReducer";
import videoReducer from "./VideoReducer";
import { socketMiddleware, socketConnect } from "./SocketMiddleware";
// Import adaptors
import { restAdaptor } from '@/adaptors';
// Define the root reducer
const rootReducer = {
    search: searchReducer,
    remote: remoteMessageReducer,
    series: seriesReducer,
    config: configReducer,
    video: videoReducer
};
// Create the store
const store = configureStore({
    reducer: rootReducer,
    middleware: (getDefaultMiddleware) => getDefaultMiddleware({
        thunk: {
            extraArgument: { restAdaptor },
        },
        // Configure serialization check to ignore non-serializable adaptor in socket actions
        serializableCheck: {
            ignoredActions: [socketConnect.type],
        },
    }).concat(socketMiddleware())
});
export default store;
