import { createAction } from '@reduxjs/toolkit';
import { createSocketAdaptor } from '@/adaptors/SocketInterface';
import { handleRemotePlayerState } from "@/domain/Store/EventReducer";
import { setIsConnected } from './VideoReducer';
// Action Types
export const socketConnect = createAction('socket/connect');
export const socketConnected = createAction('socket/connected');
export const socketDisconnect = createAction('socket/disconnect');
export const socketSend = createAction('socket/send');
export const socketRetryConnect = createAction('socket/retryConnect');
export const videoPlay = createAction('video/play');
export const videoSeek = createAction('video/seek');
export const videoTogglePause = createAction('video/togglePause');
// Socket Middleware
export const socketMiddleware = () => {
    let socket = null;
    let host = null;
    return store => next => action => {
        const result = next(action);
        if (socketConnect.match(action)) {
            if (socket) {
                socket.close();
            }
            host = action.payload;
            connectSocket(host, store);
        }
        if (socketRetryConnect.match(action) && socket) {
            socket.retryReconnect();
        }
        /*if (socketDisconnect.match(action) && socket) {
          store.dispatch(setIsConnected(false));
          socket.close();
          socket = null;
        }*/
        if (socketSend.match(action) && socket) {
            socket.send(action.payload);
        }
        return result;
    };
    // Helper function to establish socket connection
    function connectSocket(hostAdapter, store) {
        const webSocketFactory = () => {
            const socketUrl = hostAdapter.getSocketHost(location.host, location.protocol, "api/remote/ws");
            console.log(`connecting to: ${socketUrl}`);
            return new WebSocket(socketUrl);
        };
        createSocketAdaptor(webSocketFactory, (message) => {
            // Dispatch actions based on the message type
            if (typeof message.Play !== "undefined") {
                store.dispatch(videoPlay(message.Play));
            }
            else if (typeof message.Seek !== "undefined") {
                store.dispatch(videoSeek(message.Seek.interval));
            }
            else if (typeof message.TogglePause !== "undefined") {
                store.dispatch(videoTogglePause());
            }
            else {
                // Use AppDispatch to properly handle thunk actions
                store.dispatch(handleRemotePlayerState(message));
            }
        }, "remote-player").then(socketInstance => {
            socket = socketInstance;
            store.dispatch(socketConnected());
            store.dispatch(setIsConnected(true));
        }).catch(error => {
            console.error("Failed to initialize socket:", error);
            store.dispatch(setIsConnected(false));
        });
    }
};
