import { createSlice } from '@reduxjs/toolkit';
import { SE_PIRATEBAY } from '../Constants';
;
const initialState = {
    term: '',
    engine: SE_PIRATEBAY,
    results: [],
    lastSearch: '',
    addToSeries: ''
};
export const searchSlice = createSlice({
    name: 'search',
    initialState,
    reducers: {
        setTerm: (state, action) => {
            state.term = action.payload;
        },
        setEngine: (state, action) => {
            state.engine = action.payload;
        },
        setResults: (state, action) => {
            state.results = action.payload;
        },
        setLastSearch: (state, action) => {
            state.lastSearch = action.payload;
        },
        setAddToSeries: (state, action) => {
            state.addToSeries = action.payload;
        }
    }
});
export const { setTerm, setEngine, setResults, setLastSearch, setAddToSeries } = searchSlice.actions;
export default searchSlice.reducer;
